# spinel: int64 -- Integer#fdiv of operands far past 2**64 (Bignums)
# Integer#fdiv keeps a finite quotient whose operands overflow a Float.
n = 10**344
d = 9 * 10**342
p n.fdiv(d)
p (-n).fdiv(d)
p n.fdiv(-d)
p (-n).fdiv(-d)
p n.fdiv(n)
p (n + 1).fdiv(d + 3)
p (2**1100 + 12345).fdiv(2**1080 + 17)
p 3.fdiv(10**309)
p (-3).fdiv(10**309)
p (10**309).fdiv(3)
p 0.fdiv(10**344)
p (10**344).fdiv(10**1000)
p (-10**344).fdiv(10**1000)
p [n, :other][0].fdiv([d, :other][0])
p [3, :other][0].fdiv([10**309, :other][0])

base = 2**1200
[0, 1, 2, 3, 7, 13, 31, 63, 127].each do |k|
  p (base * (2**53 + k)).fdiv(base * 2**53)
  p (base * (2**53 + k)).fdiv(base * (2**53 + 7))
  p (base * (2**53 + k)).fdiv(base * 2**1127)
end
p (2**1100).fdiv(2**2174)
p (2**1100).fdiv(2**2175)
p (2**1100 + 2**1099).fdiv(2**2175)

p ().fdiv()
p ().fdiv()
p ().fdiv()
p ().fdiv()

n = [10**344].find { false }
begin
  p n.fdiv(10**342)
rescue NoMethodError => e
  p e.class
  p e.message.lines.first.strip
end
begin
  p (10**344).fdiv(n)
rescue TypeError => e
  p e.class
  p e.message
end
p n&.fdiv(10**342)
i = [3].find { false }
begin
  p (10**344).fdiv(i)
rescue TypeError => e
  p e.class
  p e.message
end
begin
  p i.fdiv(10**344)
rescue NoMethodError => e
  p e.class
  p e.message.lines.first.strip
end
